#!/bin/bash
P="$(cd "$(dirname "$0")/.." && pwd)"; cd $P/assets/raw
until grep -q PROPSDONE gen.log; do sleep 20; done
[ -s terrain.png ] || codex exec --skip-git-repo-check -s workspace-write -C $P/assets/raw "Use your image generation tool to create ONE NEW image (never reuse an existing file) and save it as $P/assets/raw/terrain.png. 1536x1024 TERRAIN TEXTURE SHEET for a 16-bit SNES-style top-down RPG: follow the attached template, 6 columns x 4 rows of 256x256 square cells, each cell completely filled edge to edge with ONE seamless tileable flat top-down ground texture named in the template (grass, dark grass, grass with tiny flowers, forest floor, dirt path, cobblestone road, plaza flagstones, sand, shallow water, deep water, volcanic ash, lava cracks, snow, snowy grass, wooden planks, rock cliff top, farmland rows, gravel, mossy stone, dry grass, tall grass, clover, mud puddle, beach pebbles). Chunky clean pixel art with BIG pixels (each art pixel about 8x8 screen pixels), limited palette, even lighting, no perspective, no objects, no shadows from objects, no borders between cells, no text." -i terrain-template.png < /dev/null > terrain.png.log 2>&1
echo "terrain.png rc=$?" >> gen.log; echo TERRAINDONE >> gen.log
